+    pub const DELTA: &'static str = "response.output_item.delta";
+
+    pub const fn as_str(&self) -> &'static str {
+        match self {
+            Self::Added => Self::ADDED,
+            Self::Done => Self::DONE,
+            Self::Delta => Self::DELTA,
+        }
+    }
+}
+
+impl fmt::Display for OutputItemEvent {
